package com.autojobapply.tracking; import com.autojobapply.model.*; import java.nio.file.*; import java.sql.*; import java.util.List;
public final class GreenhousePersistenceTest { public static void main(String[] a)throws Exception{Path p=Files.createTempFile("greenhouse",".db");try(ApplicationTracker t=new ApplicationTracker(p)){t.initialize();t.saveEmployer("x","Co","u","a","fixture",true);t.saveEmployer("x","Co2","u","a","fixture",true);Job j=new Job("Greenhouse","Co2","Staff","SF","description","1","u","u");t.saveGreenhouseJob("x",j);t.saveGreenhouseJob("x",j);t.record(new ScoredJob(j,85,List.of("java"),List.of(),true,"matched",List.of()),ApplicationStatus.APPLYING,"browser validation retained");t.enqueue("x",new ScoredJob(j,85,List.of("java"),List.of(),true,"matched",List.of()));ScoredJob queued=t.queuedJob("co2|1").orElseThrow(()->new AssertionError("queued job"));if(!"description".equals(queued.job().description())||queued.score()!=85||t.readyQueuedJobs().size()!=1)throw new AssertionError("queued details");t.markQueueIneligible("co2|1");if(t.queuedJob("co2|1").isPresent()||!t.readyQueuedJobs().isEmpty()||!"INELIGIBLE".equals(t.queueState("co2|1").orElseThrow()))throw new AssertionError("ineligible queue excluded");if(t.greenhouseJobCount()!=1)throw new AssertionError("duplicate job");}try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+p);Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT status,reason FROM applications WHERE identity='co2|1'")){if(!r.next()||!"APPLYING".equals(r.getString(1))||!"browser validation retained".equals(r.getString(2)))throw new AssertionError("application history retained");}try(ApplicationTracker t=new ApplicationTracker(p)){if(t.greenhouseJobCount()!=1)throw new AssertionError("reopen");}Files.deleteIfExists(p);System.out.println("GREENHOUSE_PERSISTENCE_TEST_PASSED");}}
